"""Scoped presentation for the asynchronously loaded CRM home card."""
STYLE = """<style>
.kc-wrap{max-width:1240px;margin:0 auto 48px;padding:0 28px;font-family:Inter,'Segoe UI',Arial,sans-serif;color:#20324e}
.kc-panel{position:relative;overflow:hidden;border:1px solid #dce6f2;border-radius:22px;background:linear-gradient(125deg,#f4f8ff 0%,#fff 47%,#f9fcff 100%);box-shadow:0 12px 36px #1d42600a}
.kc-panel:before{content:'';display:block;height:4px;background:linear-gradient(90deg,#3778d8,#6b7ee8 55%,#70c5c1)}
.kc-head{display:flex;align-items:center;justify-content:space-between;gap:22px;padding:26px 28px 22px;flex-wrap:wrap}
.kc-heading{display:flex;align-items:center;gap:15px;min-width:0}.kc-emblem{display:grid;place-items:center;width:52px;height:52px;flex-shrink:0;border-radius:16px;background:#e4edff;color:#4773c4;box-shadow:inset 0 1px 0 #fff}
.kc-panel svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}.kc-emblem svg{width:27px;height:27px}
.kc-eyebrow{font-size:10px;font-weight:800;letter-spacing:1.7px;color:#6580af;text-transform:uppercase}.kc-panel h3{font-size:22px;line-height:1.25;letter-spacing:-.6px;color:#1b3153;margin:6px 0;font-weight:800}.kc-panel p{margin:0;color:#7b8ba2;font-size:12px;line-height:1.5}
.kc-actions{display:flex;gap:9px;flex-wrap:wrap}.kc-panel a{text-decoration:none}.kc-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:40px;padding:0 15px;border-radius:11px;font-size:12px;font-weight:750;border:1px solid #dce5f3;color:#466590;background:#fff;transition:background .18s,box-shadow .18s}.kc-button.kc-primary{background:#386dcd;color:#fff;border-color:#386dcd;box-shadow:0 5px 14px #386dcd25}.kc-button:hover{background:#edf3ff}.kc-button.kc-primary:hover{background:#295db9}.kc-button svg{width:16px;height:16px}
.kc-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:0 28px 24px}.kc-stat{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:17px 19px;background:#ffffffcc;border:1px solid #e2e9f3;border-radius:14px;min-width:0;transition:border-color .18s,background .18s}.kc-stat:hover{border-color:#9ab6e4;background:#fff}.kc-stat strong{display:block;color:#263e61;font-size:30px;line-height:1.1;letter-spacing:-1px;font-weight:800}.kc-stat span{display:block;margin-top:7px;color:#7b8ba2;font-size:11px;font-weight:650}.kc-stat i{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;font-style:normal;background:#edf2fb;color:#7e96b7;flex-shrink:0}.kc-stat.kc-overdue strong{color:#c96361}.kc-stat.kc-overdue i{background:#fff0ed;color:#cf7770}.kc-stat.kc-today strong{color:#3a70c7}.kc-stat.kc-today i{background:#eaf1ff;color:#4c7ac6}
.kc-agenda{margin:0 28px;border-top:1px solid #e4ebf5;padding:18px 0 6px}.kc-agenda-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:7px}.kc-agenda h4{font-size:12px;letter-spacing:.1px;font-weight:750;color:#49627f;margin:0}.kc-agenda-title>span{font-size:10px;color:#8b9bb0}
.kc-lead{display:flex;align-items:center;gap:12px;padding:13px 9px;border-bottom:1px solid #edf1f7;border-radius:9px;color:#243b59}.kc-lead:last-child{border-bottom:0}.kc-lead:hover{background:#edf4ff}.kc-avatar{display:grid;place-items:center;width:34px;height:34px;border-radius:11px;background:#eaf0fc;color:#6987bc;font-size:12px;font-weight:800;flex-shrink:0}.kc-lead-copy{min-width:0;flex:1}.kc-lead-name{font-size:12px;font-weight:750;display:block;overflow-wrap:anywhere}.kc-lead-next{font-size:11px;line-height:1.45;display:block;color:#8796aa;margin-top:4px;overflow-wrap:anywhere}.kc-date{font-size:10px;font-weight:750;background:#eaf2ff;color:#6588bc;padding:6px 8px;border-radius:8px;white-space:nowrap}.kc-date.kc-late{background:#fff0ed;color:#b97167}.kc-lead>svg{width:14px;height:14px;color:#9aacc5}
.kc-empty{display:flex;align-items:center;gap:13px;padding:19px 8px 21px}.kc-empty>svg{color:#6baba1;width:25px;height:25px}.kc-empty strong{font-size:12px;display:block;color:#526b83;margin-bottom:4px}.kc-empty p{font-size:11px}.kc-loading{padding:20px 8px;color:#8191aa;font-size:12px}
.kc-foot{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap;padding:18px 28px;background:#f3f7fd;border-top:1px solid #e4ebf5}.kc-foot-copy{display:flex;align-items:center;gap:11px}.kc-foot-copy>svg{color:#8ba2c3}.kc-foot strong{display:block;color:#536d91;font-size:11px;margin-bottom:4px}.kc-foot p{font-size:11px}.kc-foot .kc-button{background:transparent;min-height:36px;font-size:11px}
.kc-panel a:focus-visible{outline:3px solid #79a3ee;outline-offset:3px}
@media(max-width:640px){.kc-wrap{padding:0 12px}.kc-panel{border-radius:18px}.kc-head{padding:21px 18px 18px;gap:17px}.kc-heading{gap:12px}.kc-emblem{width:44px;height:44px;border-radius:13px}.kc-emblem svg{width:23px;height:23px}.kc-panel h3{font-size:19px}.kc-panel p{font-size:11px}.kc-eyebrow{font-size:9px}.kc-actions{width:100%}.kc-actions .kc-button{flex:1;min-height:40px}.kc-stats{gap:8px;padding:0 18px 19px}.kc-stat{padding:13px 10px;align-items:flex-start;flex-direction:column-reverse;gap:10px}.kc-stat strong{font-size:27px}.kc-stat span{font-size:10px;line-height:1.35}.kc-stat i{width:27px;height:27px;border-radius:9px}.kc-stat svg{width:15px;height:15px}.kc-agenda{margin:0 18px;padding-top:16px}.kc-lead{padding:12px 0;gap:9px}.kc-lead-name{font-size:11px}.kc-lead-next{font-size:10px}.kc-date{padding:5px 6px;font-size:9px}.kc-lead>svg{display:none}.kc-foot{padding:17px 18px;gap:13px}.kc-foot>.kc-button{width:100%}.kc-foot-copy{align-items:flex-start}.kc-empty{padding:19px 0}.kc-empty p{font-size:10px}.kc-agenda-title>span{font-size:9px}}
@media(prefers-reduced-motion:reduce){.kc-button,.kc-stat{transition:none}}
</style>"""

SUMMARY = """<section class="kc-panel" aria-label="Acompanhamento de leads" aria-busy="{{ 'true' if loading else 'false' }}">
<header class="kc-head"><div class="kc-heading"><span class="kc-emblem" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg></span><div><span class="kc-eyebrow">CRM · Comercial</span><h3>Seus próximos contatos</h3><p>Reuniões, propostas e próximos retornos.</p></div></div>
<div class="kc-actions"><a class="kc-button kc-primary" href="/crm">Abrir CRM <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a><a class="kc-button" href="/crm/novo"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>Novo lead</a></div></header>
<nav class="kc-stats" aria-label="Filtrar acompanhamentos">
<a class="kc-stat {{ 'kc-overdue' if not loading and overdue else '' }}" href="/crm?prazo=atrasados"><div><strong>{{ '—' if loading else overdue }}</strong><span>Atrasados</span></div><i aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v6m0 4h.01"/></svg></i></a>
<a class="kc-stat kc-today" href="/crm?prazo=hoje"><div><strong>{{ '—' if loading else due }}</strong><span>Para hoje</span></div><i aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18m-13 5h3"/></svg></i></a>
<a class="kc-stat" href="/crm?prazo=sem_data"><div><strong>{{ '—' if loading else undated }}</strong><span>Sem data</span></div><i aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9 5H5v16h14V5h-4M9 3h6v4H9zM8 12h8M8 16h5"/></svg></i></a></nav>
<div class="kc-agenda"><div class="kc-agenda-title"><h4>Prioridades do dia</h4>{% if not loading and leads %}<span>Mais antigos primeiro</span>{% endif %}</div>
{% if loading %}<div class="kc-loading" role="status">Carregando acompanhamentos…</div>
{% else %}{% for lead in leads %}<a class="kc-lead" href="/crm/{{ lead.id }}"><span class="kc-avatar" aria-hidden="true">{{ lead.nome[:1]|upper }}</span><span class="kc-lead-copy"><strong class="kc-lead-name">{{ lead.nome }}</strong><span class="kc-lead-next">{{ lead.dados.get('proxima_acao') or 'Defina o próximo passo' }}</span></span><span class="kc-date {{ 'kc-late' if lead.data_followup < today else '' }}">{{ lead.data_followup.strftime('%d/%m') if lead.data_followup < today else 'Hoje' }}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg></a>
{% else %}<div class="kc-empty"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></svg><div><strong>Nenhum retorno pendente para hoje</strong><p>Os próximos acompanhamentos ficam no CRM.</p></div></div>{% endfor %}{% endif %}</div>
<footer class="kc-foot"><div class="kc-foot-copy"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5"/></svg><div><strong>Terminou uma reunião?</strong><p>Use a transcrição para preencher o lead.</p></div></div><a class="kc-button" href="/crm/importar">Importar transcrição <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V4m-5 5 5-5 5 5M4 16v4h16v-4"/></svg></a></footer></section>"""

# Keep a useful shell even if the independent summary request fails.
# Rendering the placeholder must not require an application context at import time.
from jinja2 import Environment, select_autoescape
_placeholder = Environment(autoescape=select_autoescape(default=True)).from_string(SUMMARY).render(loading=True)
HOME_WIDGET = STYLE + '<div class="kc-wrap"><div id="crm-home-summary">' + _placeholder + """</div></div>
<script>(function(){const root=document.getElementById('crm-home-summary');
fetch('/crm/resumo',{credentials:'same-origin'}).then(function(r){if(!r.ok)throw Error();return r.text();}).then(function(s){root.innerHTML=s;}).catch(function(){root.querySelector('.kc-panel').setAttribute('aria-busy','false');root.querySelector('.kc-loading').textContent='Não foi possível carregar os acompanhamentos. Abra o CRM para consultar.';});})();</script>"""
